prompt --application/shared_components/plugins/region_type/apex_qr_code_scanner
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(35792515642677904591)
,p_plugin_type=>'REGION TYPE'
,p_name=>'APEX.QR.CODE.SCANNER'
,p_display_name=>'APEX QR Code Scanner'
,p_apexlang_name=>'apexQrCodeScanner'
,p_image_prefix=>nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','APEX.QR.CODE.SCANNER'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION F_RENDER (',
'    P_REGION                IN APEX_PLUGIN.T_REGION,',
'    P_PLUGIN                IN APEX_PLUGIN.T_PLUGIN,',
'    P_IS_PRINTER_FRIENDLY   IN BOOLEAN',
') RETURN APEX_PLUGIN.T_REGION_RENDER_RESULT IS',
'BEGIN',
'    APEX_JAVASCRIPT.ADD_LIBRARY(',
'        P_NAME        => ''qrcodescanner.pkg.min'',',
'        P_DIRECTORY   => P_PLUGIN.FILE_PREFIX,',
'        P_VERSION     => NULL,',
'        P_KEY         => ''qrscanjssrc''',
'    );',
'',
'    APEX_JAVASCRIPT.ADD_ONLOAD_CODE( ''qrCodeScanner(apex,$).initialize(''',
'       || APEX_JAVASCRIPT.ADD_VALUE( P_REGION.STATIC_ID, TRUE )',
'       || APEX_JAVASCRIPT.ADD_VALUE( P_REGION.ATTRIBUTE_01, TRUE )',
'       || APEX_JAVASCRIPT.ADD_VALUE( TO_NUMBER(P_REGION.ATTRIBUTE_02), TRUE )',
'       || APEX_JAVASCRIPT.ADD_VALUE( P_REGION.ATTRIBUTE_03, TRUE )',
'       || APEX_JAVASCRIPT.ADD_VALUE( P_REGION.ATTRIBUTE_04, TRUE )',
'       || APEX_JAVASCRIPT.ADD_VALUE( P_REGION.ATTRIBUTE_05, FALSE )',
'       || '');'' );',
'',
'    RETURN NULL;',
'END;'))
,p_api_version=>1
,p_render_function=>'F_RENDER'
,p_substitute_attributes=>true
,p_version_scn=>'1'
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'This Region Plug-in is used to scan QR Codes. If any string has been detected an APEX Item can be set, Dynamic Action can be fired or JavaScript can be executed.',
'',
'To control the QR Code Scanner you can fire events on th QR Code region.',
'',
'The following events are supportet:',
'',
'$("#qrscanner_region").trigger("scannerPause"); => Pause the scanner',
'$("#qrscanner_region").trigger("scannerPlay"); => Restart the scanner from pause',
'$("#qrscanner_region").trigger("resetValue"); => Reset value to rescan the same QR Code if needed'))
,p_version_identifier=>'1.5.1.0'
,p_about_url=>'https://github.com/RonnyWeiss/APEX-QR-Code-Scanner'
,p_files_version=>1165
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(35792515887247904596)
,p_plugin_id=>wwv_flow_imp.id(35792515642677904591)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'attribute_01'
,p_prompt=>'ConfigJSON'
,p_apexlang_name=>'configjson'
,p_attribute_type=>'JAVASCRIPT'
,p_is_required=>true
,p_default_value=>wwv_flow_string.join(wwv_flow_t_varchar2(
'{',
'  "height": 340,',
'  "scanFrameColor": "rgba(192,0,15,1)",',
'  "facingMode": "environment",',
'  "mirrorScanner": false',
'}'))
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'{',
'  "height": 340,',
'  "scanFrameColor": "rgba(192,0,15,1)",',
'  "facingMode": "environment",',
'  "mirrorScanner": false',
'}',
'</pre>',
'<br>',
'<h3>Explanation:</h3>',
'<ul>',
'<li><strong>height (number)</strong>: height of the canvas</li>',
'<li><strong>scanFrameColor (string)</strong>: color of the border frame when qr code had been detected</li>',
'<li><strong>facingMode (string)</strong>: choose camera e.g. on mobile phones',
'<ul>',
'<li><strong>"user"</strong>: The video source is facing toward the user; this includes, for example, the front-facing camera on a smartphone.</li>',
'<li><strong>"environment"</strong>: The video source is facing away from the user, thereby viewing their environment. This is the back camera on a smartphone.</li>',
'<li><strong>"left"</strong>: The video source is facing toward the user but to their left, such as a camera aimed toward the user but over their left shoulder.</li>',
'<li><strong>"right"</strong>: The video source is facing toward the user but to their right, such as a camera aimed toward the user but over their right shoulder.</li>',
'</ul>',
'</li>',
'<li><strong>mirrorScanner (boolean)</strong>: mirror the whole video output</li>',
'</ul>'))
);
