,p_list_template_name=>'Top Navigation Menu'
,p_static_id=>'top-navigation-menu'
,p_internal_name=>'TOP_NAVIGATION_MENU'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
